package org.usbworkbench;
import java.io.*;import java.security.SecureRandom;import java.util.*;

/** Original MBR layout writer. User-imported boot data; verified before partition-table commit. */
public final class VentoyInstaller {
 public static long part2(long sectors)throws IOException {if(sectors<262144||sectors>0xffffffffL)throw new IOException("VENTOY_SIZE");return (sectors-65536)&~7L;}
 static BlockDevice verified(BlockDevice disk){return new BlockDevice(){public int blockSize(){return disk.blockSize();}public long blockCount(){return disk.blockCount();}public void read(long at,byte[] b,int n)throws IOException{disk.read(at,b,n);}public void write(long at,byte[] b,int n)throws IOException{disk.write(at,b,n);byte[] actual=new byte[n];disk.read(at,actual,n);for(int i=0;i<n;i++)if(b[i]!=actual[i])throw new IOException("VERIFY_FAILED");}public void sync()throws IOException{disk.sync();}public void close(){}};}
 public static void updateMbr(BlockDevice target,VentoyBundle imported,DiskTools.Progress p)throws IOException {
  if(target.blockSize()!=512)throw new IOException("FAT_SECTOR");part2(target.blockCount());VentoyBundle bundle=VentoyBundle.load(imported.directory);byte[] old=new byte[512];target.read(0,old,512);
  long start=OpticalImage.u32(old,470);if(old[510]!=85||(old[511]&255)!=170||(old[450]&255)!=7||(old[466]&255)!=239||OpticalImage.u32(old,454)!=2048||OpticalImage.u32(old,458)!=start-2048||OpticalImage.u32(old,474)!=65536||start<131072||start%8!=0||start>target.blockCount()-65536)throw new IOException("VENTOY_UPDATE_LAYOUT");
  for(int off=478;off<510;off++)if(old[off]!=0)throw new IOException("VENTOY_UPDATE_LAYOUT");
  byte[] efi=new byte[512];target.read(start,efi,512);if(!new String(efi,43,11,java.nio.charset.StandardCharsets.US_ASCII).equals("VTOYEFI    ")||!new String(efi,54,8,java.nio.charset.StandardCharsets.US_ASCII).equals("FAT16   "))throw new IOException("VENTOY_UPDATE_LAYOUT");
  byte[] boot=new byte[512],expected=new byte[512],actual=new byte[512];try(InputStream in=new FileInputStream(bundle.file("boot.img"))){DiskTools.readFully(in,boot,512);}try(InputStream in=new FileInputStream(bundle.file("core.img"))){DiskTools.readFully(in,expected,512);}target.read(1,actual,512);for(int i=0;i<32;i++)if(actual[i]!=expected[i])throw new IOException("VENTOY_UPDATE_LAYOUT");
  BlockDevice disk=verified(target);long length=VentoyBundle.CORE_BYTES-4096,done=0;byte[] buffer=new byte[65536];try(InputStream in=new FileInputStream(bundle.file("core.img"))){while(done<length){p.update(done,length+VentoyBundle.EFI_BYTES);int n=(int)Math.min(buffer.length,length-done);DiskTools.readFully(in,buffer,n);disk.write(1+done/512,buffer,n);done+=n;}}
  copy(bundle.file("efi.img"),disk,start,p);disk.sync();System.arraycopy(old,384,boot,384,16);System.arraycopy(old,440,boot,440,72);disk.write(0,boot,512);disk.sync();p.update(1,1);
 }
 private static void copy(File file,BlockDevice disk,long sector,DiskTools.Progress p)throws IOException {byte[] b=new byte[65536];long bytes=file.length(),done=0;try(InputStream in=new FileInputStream(file)){while(done<bytes){p.update(done,bytes);int n=(int)Math.min(b.length,bytes-done);DiskTools.readFully(in,b,n);disk.write(sector+done/512,b,n);done+=n;}if(in.read()!=-1)throw new IOException("VENTOY_ASSET_CHANGED");}}
 public static void install(BlockDevice target,VentoyBundle imported,DiskTools.Progress p)throws IOException {
  if(target.blockSize()!=512)throw new IOException("FAT_SECTOR");long part2=part2(target.blockCount());new AdvancedDiskTools.ExFatLayout(part2,0);
  VentoyBundle bundle=VentoyBundle.load(imported.directory); // Recheck all imported hashes/geometry before ANY write.
  byte[] mbr=new byte[512];try(InputStream in=new FileInputStream(bundle.file("boot.img"))){DiskTools.readFully(in,mbr,512);}Arrays.fill(mbr,446,510,(byte)0);byte[] random=new byte[16];SecureRandom secure=new SecureRandom();secure.nextBytes(random);System.arraycopy(random,0,mbr,384,16);secure.nextBytes(random);System.arraycopy(random,0,mbr,440,4);mbr[444]=mbr[445]=0;
  partition(mbr,446,0x80,7,2048,part2-2048);partition(mbr,462,0,0xef,part2,65536);mbr[510]=85;mbr[511]=(byte)170;
  BlockDevice disk=verified(target);p.update(0,1);disk.write(0,new byte[512],512);for(long at=target.blockCount()-33;at<target.blockCount();at++)disk.write(at,new byte[512],512);
  BlockDevice prefix=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return part2;}public void read(long at,byte[] b,int n)throws IOException{bounds(at,n);disk.read(at,b,n);}private void bounds(long at,int n)throws IOException{if(at<0||n<0||n%512!=0||at>part2||n/512>part2-at)throw new IOException("DISK_BOUNDS");}public void write(long at,byte[] b,int n)throws IOException{bounds(at,n);if(at==0){if(n!=512)throw new IOException("DISK_BOUNDS");return;}disk.write(at,b,n);}public void sync()throws IOException{disk.sync();}public void close(){}};
  AdvancedDiskTools.formatExFat(prefix,"Ventoy",0,p);copy(bundle.file("core.img"),disk,1,p);copy(bundle.file("efi.img"),disk,part2,p);disk.sync();
  p.update(0,1);disk.write(0,mbr,512);disk.sync();byte[] check=new byte[512];disk.read(0,check,512);if(!Arrays.equals(check,mbr))throw new IOException("VERIFY_FAILED");p.update(1,1);
 }

 public static long part2Gpt(long sectors)throws IOException{part2(sectors);return (sectors-65536-33)&~7L;}
 private static byte[] gptBoot(VentoyBundle bundle)throws IOException{byte[] boot=new byte[512];try(InputStream in=new FileInputStream(bundle.file("boot.img"))){DiskTools.readFully(in,boot,512);}Arrays.fill(boot,446,510,(byte)0);boot[92]=0x22;return boot;}
 private static void gptEntry(byte[] entries,int at,long start,long end,String name,boolean hidden){System.arraycopy(AdvancedDiskTools.guid(UUID.fromString("EBD0A0A2-B9E5-4433-87C0-68B6B72699C7")),0,entries,at,16);System.arraycopy(AdvancedDiskTools.guid(UUID.randomUUID()),0,entries,at+16,16);AdvancedDiskTools.le64(entries,at+32,start);AdvancedDiskTools.le64(entries,at+40,end);if(hidden)entries[at+55]=(byte)128;byte[] text=name.getBytes(java.nio.charset.StandardCharsets.UTF_16LE);System.arraycopy(text,0,entries,at+56,text.length);}
 private static void gptCore(BlockDevice disk,VentoyBundle bundle,boolean update,DiskTools.Progress p)throws IOException{
  long bytes=(update?2006L:2014L)*512,done=0;byte[] b=new byte[65536];try(InputStream in=new FileInputStream(bundle.file("core.img"))){while(done<bytes){p.update(done,bytes);int n=(int)Math.min(b.length,bytes-done);DiskTools.readFully(in,b,n);if(done==0)b[500]=0x23;disk.write(34+done/512,b,n);done+=n;}}
 }
 public static void installGpt(BlockDevice target,VentoyBundle imported,DiskTools.Progress p)throws IOException{
  if(target.blockSize()!=512)throw new IOException("FAT_SECTOR");long part2=part2Gpt(target.blockCount()),last=target.blockCount()-1;new AdvancedDiskTools.ExFatLayout(part2,0);VentoyBundle bundle=VentoyBundle.load(imported.directory);
  byte[] boot=gptBoot(bundle),entries=new byte[16384];SecureRandom random=new SecureRandom();byte[] identity=new byte[16];random.nextBytes(identity);System.arraycopy(identity,0,boot,384,16);random.nextBytes(identity);System.arraycopy(identity,0,boot,440,4);partition(boot,446,0,0xee,1,last);gptEntry(entries,0,2048,part2-1,"Ventoy",false);gptEntry(entries,128,part2,part2+65535,"VTOYEFI",true);byte[] id=AdvancedDiskTools.guid(UUID.randomUUID());long crc=AdvancedDiskTools.crc(entries,entries.length);byte[] primary=AdvancedDiskTools.gptHeader(1,last,2,last,id,crc),backup=AdvancedDiskTools.gptHeader(last,1,last-32,last,id,crc);
  BlockDevice disk=verified(target);p.update(0,1);disk.write(0,new byte[512],512);
  BlockDevice prefix=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return part2;}public void read(long at,byte[] b,int n)throws IOException{disk.read(at,b,n);}public void write(long at,byte[] b,int n)throws IOException{if(at<0||at>part2||n/512>part2-at||n%512!=0)throw new IOException("DISK_BOUNDS");if(at==0){if(n!=512)throw new IOException("DISK_BOUNDS");return;}disk.write(at,b,n);}public void sync()throws IOException{disk.sync();}public void close(){}};
  AdvancedDiskTools.formatExFat(prefix,"Ventoy",0,p);gptCore(disk,bundle,false,p);copy(bundle.file("efi.img"),disk,part2,p);disk.sync();
  p.update(0,1);disk.write(last-32,entries,entries.length);disk.write(last,backup,512);disk.write(2,entries,entries.length);disk.write(1,primary,512);disk.sync();AdvancedDiskTools.inspectGpt(disk);p.update(0,1);disk.write(0,boot,512);disk.sync();p.update(1,1);
 }
 public static void updateGpt(BlockDevice target,VentoyBundle imported,DiskTools.Progress p)throws IOException{
  if(target.blockSize()!=512)throw new IOException("FAT_SECTOR");long part2=part2Gpt(target.blockCount());VentoyBundle bundle=VentoyBundle.load(imported.directory);byte[] old=new byte[512],head=new byte[512],entries=new byte[16384];target.read(0,old,512);target.read(1,head,512);
  if((old[450]&255)!=238||old[92]!=0x22||old[510]!=85||(old[511]&255)!=170||OpticalImage.u32(old,454)!=1||OpticalImage.u32(old,458)!=target.blockCount()-1)throw new IOException("VENTOY_UPDATE_LAYOUT");for(int i=462;i<510;i++)if(old[i]!=0)throw new IOException("VENTOY_UPDATE_LAYOUT");
  if(!AdvancedDiskTools.inspectGpt(target).contains("CRC OK")||OpticalImage.u64(head,72)!=2||OpticalImage.u32(head,80)!=128||OpticalImage.u32(head,84)!=128||OpticalImage.u64(head,40)!=34||OpticalImage.u64(head,48)!=target.blockCount()-34)throw new IOException("VENTOY_UPDATE_LAYOUT");target.read(2,entries,entries.length);
  byte[] type=AdvancedDiskTools.guid(UUID.fromString("EBD0A0A2-B9E5-4433-87C0-68B6B72699C7"));for(int at:new int[]{0,128}){for(int j=0;j<16;j++)if(entries[at+j]!=type[j])throw new IOException("VENTOY_UPDATE_LAYOUT");long start=OpticalImage.u64(entries,at+32),end=OpticalImage.u64(entries,at+40);if(start!=(at==0?2048:part2)||end!=(at==0?part2-1:part2+65535))throw new IOException("VENTOY_UPDATE_LAYOUT");for(int j=48;j<56;j++)if(entries[at+j]!=(at==128&&j==55?(byte)128:0))throw new IOException("VENTOY_UPDATE_LAYOUT");String name=new String(entries,at+56,72,java.nio.charset.StandardCharsets.UTF_16LE).split("\u0000",2)[0];if(!name.equals(at==0?"Ventoy":"VTOYEFI"))throw new IOException("VENTOY_UPDATE_LAYOUT");}for(int i=256;i<entries.length;i++)if(entries[i]!=0)throw new IOException("VENTOY_UPDATE_LAYOUT");
  byte[] sector=new byte[512],expected=new byte[512];target.read(part2,sector,512);if(!new String(sector,43,11,java.nio.charset.StandardCharsets.US_ASCII).equals("VTOYEFI    ")||!new String(sector,54,8,java.nio.charset.StandardCharsets.US_ASCII).equals("FAT16   "))throw new IOException("VENTOY_UPDATE_LAYOUT");target.read(34,sector,512);try(InputStream in=new FileInputStream(bundle.file("core.img"))){DiskTools.readFully(in,expected,512);}for(int i=0;i<32;i++)if(sector[i]!=expected[i])throw new IOException("VENTOY_UPDATE_LAYOUT");if(sector[500]!=0x23)throw new IOException("VENTOY_UPDATE_LAYOUT");
  BlockDevice disk=verified(target);gptCore(disk,bundle,true,p);copy(bundle.file("efi.img"),disk,part2,p);disk.sync();byte[] boot=gptBoot(bundle);System.arraycopy(old,384,boot,384,16);System.arraycopy(old,440,boot,440,72);p.update(0,1);disk.write(0,boot,512);disk.sync();p.update(1,1);
 }
 private static void partition(byte[] mbr,int at,int active,int type,long start,long count){mbr[at]=(byte)active;mbr[at+1]=(byte)254;mbr[at+2]=mbr[at+3]=(byte)255;mbr[at+4]=(byte)type;mbr[at+5]=(byte)254;mbr[at+6]=mbr[at+7]=(byte)255;DiskTools.le32(mbr,at+8,start);DiskTools.le32(mbr,at+12,count);}
}
